// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { IconButton } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Actions/IconButton)

figma.connect(IconButton, FIGMA_NODE_URL, {
  props: {
    label: figma.string('label'),
    icon: figma.boolean('hasIcon', { true: figma.instance('icon'), false: undefined }),
    variant: figma.enum('variant', { 'solid': 'solid', 'subtle': 'subtle', 'ghost': 'ghost' }),
    size: figma.enum('size', { 'sm': 'sm', 'md': 'md', 'lg': 'lg' }),
  },
  example: ({ label, icon, variant, size }) => (
    <IconButton icon={icon} variant={variant} size={size}>{label}</IconButton>
  ),
});
